-- =====================================================================
-- College LMS — RESET + FULL DATA for ATSS College (code ATSS01)
-- Run AFTER 00_schema.sql and 01_schema_additions.sql, in the Supabase SQL editor.
--
-- !!! THIS DELETES DATA !!!  Everything is removed EXCEPT:
--     * the college ATSS01  (id 6d246a80-83cc-4531-8c5e-b32949fc1089)  — row kept exactly as it is
--     * its departments Science (SCI) and Commerce (COMM) — kept as they are
--     * the two HOD accounts linked to those departments
--     * every Super Admin account
--   All other colleges, users, students, marks, fees … are deleted, then fresh linked data is loaded.
--   Take a backup first (Supabase → Database → Backups) if you might need the old data.
--
-- Flow of the data:  Department → Course → Class → Semester → Subject → Teacher allocation → Timetable
--                    → Students & parents → Attendance / assignments / quizzes / feedback → Exams → Marks → Results
--
-- Password for every NEW account:  Lms@2026   (the kept HOD and Super Admin passwords are unchanged)
--   College admin    admin@atss-lms.in        Principal   principal@atss-lms.in
--   Accounts         accounts@atss-lms.in     Exams       exam@atss-lms.in
--   Admissions       admission@atss-lms.in    Library     library@atss-lms.in
--   TPO              tpo@atss-lms.in          Activities  activity@atss-lms.in
--   Sub admin        subadmin@atss-lms.in
--   Class teacher    rohit.jadhav@atss-lms.in   (class teacher of BCA - SY)
--   Subject teacher  revati.apte@atss-lms.in
--   Student          roll number BCASY01  (or that student's email)
--   Parent           vijay.patil@parents.atss-lms.in  (parent of BCASY01)
--
-- Row counts: users=400, profiles=400, user_roles=400, academic_years=3, programs=6, semesters=32, subjects=128, classes=48, divisions=16, subject_assignments=64, timetable=320, admission_applications=210, enquiries=32, students=184, parents=184, parent_student_links=184, promotions=167, academic_progression=303, result_imports=2, assignments=128, assignment_submissions=637, study_materials=64, quizzes=21, quiz_attempts=185, exams=128, exam_results=736, internal_marks=736, fee_structures=48, student_fees=552, fee_payments=474, library_books=60, library_issues=96, placements=97, tpo_records=15, clubs=8, club_enrollments=144, competitions=10, competition_registrations=107, activity_marks=222, certificates=184, announcements=20, feedback_forms=22, feedback_responses=183, audit_logs=4
-- plus attendance generated from the timetable (about 15,000 rows).
-- =====================================================================
begin;

do $$
declare c uuid := '6d246a80-83cc-4531-8c5e-b32949fc1089'; keep uuid[];
begin
  if not exists (select 1 from public.colleges where id = c) then
    raise exception 'College ATSS01 (id %) was not found. Nothing was changed.', c;
  end if;
  if (select count(*) from public.departments where id in ('39cfae1d-7e4f-486f-a868-905fa364946e','d424a1e3-11b6-4eed-a0b7-ef7f060e9fa0') and college_id = c) < 2 then
    raise exception 'The Science / Commerce departments of ATSS01 were not found. Nothing was changed.';
  end if;
  keep := array(select r.user_id from public.user_roles r join public.users u on u.id = r.user_id where r.role = 'super_admin'
                  and (u.email <> 'superadmin@kdrtlms.in' or (select count(*) from public.user_roles where role = 'super_admin') = 1)
                union select hod_user_id from public.departments where college_id = c and hod_user_id is not null);

  if to_regclass('public.feedback_responses') is not null then execute 'delete from public.feedback_responses'; end if;
  if to_regclass('public.feedback_forms') is not null then execute 'delete from public.feedback_forms'; end if;
  if to_regclass('public.assignment_submissions') is not null then execute 'delete from public.assignment_submissions'; end if;
  if to_regclass('public.quiz_attempts') is not null then execute 'delete from public.quiz_attempts'; end if;
  if to_regclass('public.exam_results') is not null then execute 'delete from public.exam_results'; end if;
  if to_regclass('public.hall_tickets') is not null then execute 'delete from public.hall_tickets'; end if;
  if to_regclass('public.attendance') is not null then execute 'delete from public.attendance'; end if;
  if to_regclass('public.internal_marks') is not null then execute 'delete from public.internal_marks'; end if;
  if to_regclass('public.academic_progression') is not null then execute 'delete from public.academic_progression'; end if;
  if to_regclass('public.activity_marks') is not null then execute 'delete from public.activity_marks'; end if;
  if to_regclass('public.certificates') is not null then execute 'delete from public.certificates'; end if;
  if to_regclass('public.placements') is not null then execute 'delete from public.placements'; end if;
  if to_regclass('public.promotions') is not null then execute 'delete from public.promotions'; end if;
  if to_regclass('public.fee_payments') is not null then execute 'delete from public.fee_payments'; end if;
  if to_regclass('public.student_fees') is not null then execute 'delete from public.student_fees'; end if;
  if to_regclass('public.fee_structures') is not null then execute 'delete from public.fee_structures'; end if;
  if to_regclass('public.library_issues') is not null then execute 'delete from public.library_issues'; end if;
  if to_regclass('public.library_books') is not null then execute 'delete from public.library_books'; end if;
  if to_regclass('public.club_enrollments') is not null then execute 'delete from public.club_enrollments'; end if;
  if to_regclass('public.club_memberships') is not null then execute 'delete from public.club_memberships'; end if;
  if to_regclass('public.clubs') is not null then execute 'delete from public.clubs'; end if;
  if to_regclass('public.competition_registrations') is not null then execute 'delete from public.competition_registrations'; end if;
  if to_regclass('public.competitions') is not null then execute 'delete from public.competitions'; end if;
  if to_regclass('public.parent_student_links') is not null then execute 'delete from public.parent_student_links'; end if;
  if to_regclass('public.parents') is not null then execute 'delete from public.parents'; end if;
  if to_regclass('public.feedback') is not null then execute 'delete from public.feedback'; end if;
  if to_regclass('public.announcements') is not null then execute 'delete from public.announcements'; end if;
  if to_regclass('public.study_materials') is not null then execute 'delete from public.study_materials'; end if;
  if to_regclass('public.quizzes') is not null then execute 'delete from public.quizzes'; end if;
  if to_regclass('public.assignments') is not null then execute 'delete from public.assignments'; end if;
  if to_regclass('public.exams') is not null then execute 'delete from public.exams'; end if;
  if to_regclass('public.timetable') is not null then execute 'delete from public.timetable'; end if;
  if to_regclass('public.tpo_records') is not null then execute 'delete from public.tpo_records'; end if;
  if to_regclass('public.result_imports') is not null then execute 'delete from public.result_imports'; end if;
  if to_regclass('public.subject_assignments') is not null then execute 'delete from public.subject_assignments'; end if;
  if to_regclass('public.enquiries') is not null then execute 'delete from public.enquiries'; end if;
  if to_regclass('public.students') is not null then execute 'delete from public.students'; end if;
  if to_regclass('public.admission_applications') is not null then execute 'delete from public.admission_applications'; end if;
  if to_regclass('public.divisions') is not null then execute 'delete from public.divisions'; end if;
  if to_regclass('public.subjects') is not null then execute 'delete from public.subjects'; end if;
  if to_regclass('public.classes') is not null then execute 'delete from public.classes'; end if;
  if to_regclass('public.semesters') is not null then execute 'delete from public.semesters'; end if;
  if to_regclass('public.programs') is not null then execute 'delete from public.programs'; end if;
  if to_regclass('public.academic_years') is not null then execute 'delete from public.academic_years'; end if;
  if to_regclass('public.audit_logs') is not null then execute 'delete from public.audit_logs'; end if;
  if to_regclass('public.otp_verifications') is not null then execute 'delete from public.otp_verifications'; end if;
  delete from public.departments where college_id <> c;
  update public.departments set hod_user_id = null where college_id = c and hod_user_id is not null and not (hod_user_id = any(keep));
  delete from public.user_roles where not (user_id = any(keep) and (role = 'super_admin' or college_id = c));
  delete from public.profiles where not (id = any(keep));
  delete from public.users where not (id = any(keep));
  delete from public.colleges where id <> c;
end $$;


